sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

	var GetAppRecord = x_snc_devtools.GetAppRecord;
	var GetStringValue = x_snc_devtools.GetStringValue;
	var IsUserHasRoleExactly = x_snc_devtools.IsUserHasRoleExactly;
	var GetParam = x_snc_devtools.GetParam;
	var GetArrayValue = x_snc_devtools.GetArrayValue;
	var IsValidScope = x_snc_devtools.IsValidScope;
	var IsValidPluginId = x_snc_devtools.IsValidPluginId;
	var IsValidAppName = x_snc_devtools.IsValidAppName;
	var IsValidSysId = x_snc_devtools.IsValidSysId;



	function Error(strMessage,strDetails)
	{
		var myError = new sn_ws_err.ServiceError();
		myError.setStatus(200);
		myError.setMessage(strMessage);
		myError.setDetail(strDetails);
		response.setError(myError);	
	}

	if (IsUserHasRoleExactly('x_snc_deployer.api_target') == false)
	{
		Error('User Not Authorized','');
		return;
	}

	if (IsActive() == false)
	{
		Error('INACTIVE','The Deployer app is inactive.');
		return;
	}

	function IsValidPluginWhitelist(strParam)
	{
		strParam = GetStringValue(strParam);
		var aWhitelist = GetArrayValue(strParam);
		for (var nWhitelist = 0; nWhitelist < aWhitelist.length; nWhitelist++)
		{
			var strWhitelist = aWhitelist[nWhitelist];
			var bValid = false;
			if (IsValidSysId(strWhitelist) == true)
			{
				bValid = true;
			}
			else if (IsValidPluginId(strWhitelist) == true)
			{
				bValid = true;
			}
			else if (IsValidAppName(strWhitelist) == true)
			{
				bValid = true;
			}
			if (bValid == false)
			{
				return false;
			}
		}
		return true;
	}

	function IsValidStoreAppWhitelist(strParam)
	{
		strParam = GetStringValue(strParam);
		var aWhitelist = GetArrayValue(strParam);
		for (var nWhitelist = 0; nWhitelist < aWhitelist.length; nWhitelist++)
		{
			var strWhitelist = aWhitelist[nWhitelist];
			var bValid = false;
			if (IsValidSysId(strWhitelist) == true)
			{
				bValid = true;
			}
			else if (IsValidScope(strWhitelist) == true)
			{
				bValid = true;
			}
			else if (IsValidAppName(strWhitelist) == true)
			{
				bValid = true;
			}
			if (bValid == false)
			{
				return false;
			}
		}
		return true;
	}


	var aPlugins = GetArrayValue(GetParam('plugins',IsValidPluginWhitelist));


	var aStoreApps = GetArrayValue(GetParam('store_apps',IsValidStoreAppWhitelist));

	var status = GetStatus(aPlugins,aStoreApps);

	status.message = 'SUCCESS';
	status.detail = 'Status is OK.';

	status.plugins_reflection = x_snc_devtools.RenderValue(aPlugins);

	response.setBody(status);

	return;

})(request, response);
